write(10,'ru',ru,{3:'Нахождение выражено прямо.',4:'Оруженосец не захотел; меч не имеет притяжательного определения.',6:'Глагол умереть повторён.',7:'Подлежащее при побежали не уточняется как все.',9:'Выражено унесение головы и оружия; перед отдельно не названо.',10:'Сохранён череп; выражено прикрепление.',12:'Назван теревинф.',13:'Сохранены неверность и её проявление; спрашивание относится к духу мёртвых.'})
